function lapClient(G, C) {
  const $ = q => document.querySelector(q);
  let TAB = 1;
  const list = () => G.stages().map((s, i) => ({ s, i })).filter(x => G.st(x.s.id));   // 周目分頁裡能打的關卡（照順序；含特殊關卡）
  // 「最後一關」＝最後一個一般關卡（特殊關卡 special 不算：打倒它不開下一個周目分頁，2026-11-17 元宵節）
  const last = () => { const L = list().filter(x => !x.s.special); return L.length ? L[L.length - 1].s : null; };
  function clearedAt(c, s, n) {   // 這一關的第 n 周目 MVP 打倒了沒
    if (!c || !s) return false;
    if (n <= 1) return G.zd(c.mvpsDefeated || [], s.mvp.id);
    return ((c.roLap && c.roLap[s.id]) | 0) >= n;
  }
  const tabOpen = (c, n) => n <= 1 || clearedAt(c, last(), n - 1);   // 第 n 周目分頁：打倒第 n−1 周目最後一關的 MVP
  const maxTab = c => { let n = 1; while (n < C.max && tabOpen(c, n + 1)) n++; return n; };
  const gsNeed = (s, n) => (n > 1 && s ? G.k(s.id, n).gs : (s && s.gsMin) || 0);
  // 周目分頁裡的解鎖判斷（形狀同原本的 eh()）
  function eh(c, i, gs) {
    const s = G.stages()[i], n = TAB, L = list(), k = L.findIndex(x => x.i === i);
    if (!s || k < 0) return { needMvp: null, mvpOk: false, gsOk: false, jobOk: false, unlocked: false, cleared: false, storyOk: true, closed: true, lapSkip: !!s && !!s.storyOnly };   // lapSkip＝劇情關，周目不重打（清單、條件改顯示說明）
    // 前一關（同 95_festival RO_FSPREV）：一般關卡＝前面最近的一般關卡（特殊關卡不擋後面的關）；
    //   特殊關卡＝緊鄰的前一關、同周目（2026-11-17 兩個特殊關卡串起來：聖誕節・改 要迷宮森林・改，元宵節・改 要聖誕節・改）
    const P = s.special ? L.slice(0, k) : L.slice(0, k).filter(x => !x.s.special), prev = P.length ? P[P.length - 1].s : null, mvpOk = prev ? clearedAt(c, prev, n) : tabOpen(c, n);
    const gsOk = gs >= gsNeed(s, n), jobOk = !s.jobLvMin || c.jobLevel >= s.jobLvMin;
    return { needMvp: prev, mvpOk, gsOk, jobOk, unlocked: mvpOk && gsOk && jobOk, cleared: clearedAt(c, s, n), storyOk: true, closed: true };
  }
  // 分頁列（關卡視窗上面）。rerender＝視窗的重畫函式，setSel＝改選到的關卡
  function tabs(c, rerender, setSel) {
    const mx = maxTab(c);
    if (TAB > mx) TAB = mx;
    let bar = document.getElementById('lap-tabs');
    const listEl = document.getElementById('stg-list');
    if (!listEl) return;
    if (!bar) { bar = document.createElement('div'); bar.id = 'lap-tabs'; bar.style.cssText = 'display:flex;gap:6px;margin:0 0 8px;flex-wrap:wrap'; listEl.parentNode.insertBefore(bar, listEl); }
    bar.classList.toggle('hidden', mx < 2);
    bar.innerHTML = C.label.slice(0, mx).map((t, k) => `<button type="button" class="ro-btn small${k + 1 === TAB ? ' primary' : ''}" data-laptab="${k + 1}">${t}</button>`).join('');
    for (const b of bar.querySelectorAll('[data-laptab]')) b.onclick = () => {
      TAB = +b.dataset.laptab;
      // 選到這個分頁裡最後一個開放的關卡
      let gs = 0; try { gs = G.gs(c); } catch {}
      const ok = list().filter(x => (TAB > 1 ? eh(c, x.i, gs) : G.eh0(c, x.i, gs)).unlocked);
      if (ok.length) setSel(ok[ok.length - 1].i);
      tabs(c, rerender, setSel); rerender();
    };
  }

return { tab: () => TAB, eh, tabs };
}
